import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, DirectionalLight, CircleGeometry, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { texture, uv, vec3, mix, smoothstep, uniform, time, positionLocal, normalLocal, add, mul, float, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Load textures ---
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = config.depthMapUrl || '/prism-mock/home/nodes/parallax-stack.depth.png';

  // Create placeholder material
  const planeMat = new MeshStandardNodeMaterial({
    color: new Color('#e8ecf2'),
    metalness: 0.3,
    roughness: 0.5,
    clearcoat: 0.1,
    side: 2, // DoubleSide
  });

  // Load textures asynchronously
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    planeMat.map = tex;
    planeMat.needsUpdate = true;
  });
  ctx.textureLoader.loadTexture(depthUrl).then((depthTex) => {
    // Set up displacement using TSL
    const depthNode = texture(depthTex, uv());
    const displacementScale = float(0.1);
    const displacement = mul(depthNode, displacementScale);
    const newPosition = add(positionLocal, mul(normalLocal, displacement));
    planeMat.positionNode = newPosition;
    planeMat.needsUpdate = true;
  });

  // Create plane geometry
  const width = 2.5;
  const height = 0.5;
  const segments = 64;
  const geometry = new PlaneGeometry(width, height, segments, segments);
  const plane = new Mesh(geometry, planeMat);
  group.add(plane);

  // --- Subtle divider line ---
  const dividerMat = new MeshBasicNodeMaterial({ color: new Color('#16161d') }); // ink color
  const dividerGeo = new PlaneGeometry(width - 0.4, 0.01);
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.y = -height / 2 - 0.05; // below the plane
  group.add(divider);

  // --- Rim light (accent) ---
  const rimLight = new DirectionalLight(new Color('#ff2a38'), 0.8);
  rimLight.position.set(-1, 1, 2); // behind and to the left
  group.add(rimLight);

  // --- Contact shadow plane ---
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    transparent: true,
    opacity: 0.5,
  });
  // Use a custom opacity node for radial gradient
  const shadowUv = uv();
  const dist = length(sub(shadowUv, vec2(0.5, 0.5)));
  const shadowOpacity = smoothstep(0.5, 0.0, dist); // fade from center
  shadowMat.opacityNode = mul(float(0.5), shadowOpacity);
  const shadowGeo = new CircleGeometry(1.5, 32);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.y = -height / 2 - 0.02; // just below the plane
  shadowMesh.rotation.x = -Math.PI / 2;
  group.add(shadowMesh);

  // --- Rim light (accent) ---
  const rimLight = new DirectionalLight(new Color('#ff2a38'), 0.8);
  rimLight.position.set(-1, 1, 2);
  group.add(rimLight);

  // --- Weighted-settle entrance ---
  const entranceTimeline = gsap.timeline();
  group.scale.set(1.04, 1.04, 1.04);
  entranceTimeline.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  // --- Hover rise-in ---
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, {
    y: group.position.y + 0.15,
    duration: 0.5,
    ease: 'power3.out',
  });

  // --- Click handler ---
  const clickHandler = () => {
    ctx.emit('navigate', { to: 'hub-pricing' }); // or 'hub-pricing.select'? Spec says emit:hub-pricing.select
    ctx.emit('hub-pricing.select', {});
  };

  // Attach handlers
  group.userData.handlers = {
    pointerenter: () => {
      hoverTimeline.play();
    },
    pointerleave: () => {
      hoverTimeline.reverse();
    },
    click: clickHandler,
  };

  // --- Apply cinematic primitives ---
  const primitiveCleanups = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result && result.cleanup) {
        primitiveCleanups.push(result.cleanup);
      }
    }
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    entranceTimeline.kill();
    hoverTimeline.kill();
    primitiveCleanups.forEach(fn => fn());
    // Dispose geometry and material
    plane.geometry.dispose();
    plane.material.dispose();
    divider.geometry.dispose();
    divider.material.dispose();
    shadow.geometry.dispose();
    shadow.material.dispose();
  };

  return group;
}
